-- MySQL import script generated from the fact_Production worksheet
-- Source rows: 10,000

CREATE DATABASE IF NOT EXISTS `manufacturing_db`
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `manufacturing_db`;


DROP TABLE IF EXISTS `FACT_PRODUCTION`;
CREATE TABLE `FACT_PRODUCTION` (
  `Doc_Num` VARCHAR(32) NULL,
  `Date_FK` DATE NULL,
  `Buyer_ID` VARCHAR(20) NULL,
  `Customer_Code` VARCHAR(30) NULL,
  `Employee_Code` VARCHAR(30) NULL,
  `Machine_Code` VARCHAR(30) NULL,
  `Operation_Code` VARCHAR(30) NULL,
  `Dept_ID` VARCHAR(20) NULL,
  `Item_Code` VARCHAR(100) NULL,
  `Delivery_Status` VARCHAR(20) NULL,
  `Is_Repeat_Order` VARCHAR(10) NULL,
  `WO_Qty` BIGINT NULL,
  `Press_Qty` BIGINT NULL,
  `Processed_Qty` BIGINT NULL,
  `Produced_Qty` BIGINT NULL,
  `Rejected_Qty` BIGINT NULL,
  `Today_Manufactured_Qty` BIGINT NULL,
  `Total_Qty` BIGINT NULL,
  `Total_Value` DECIMAL(18,2) NULL,
  `Per_Day_Machine_Cost` DECIMAL(18,2) NULL,
  `Rejection_Rate_Pct` DECIMAL(10,4) NULL,
  `Efficiency_Rate_Pct` DECIMAL(10,4) NULL,
  `Machine_Utilization_Pct` DECIMAL(10,4) NULL,
  `Cost_per_Unit` DECIMAL(18,4) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;





















-- Verification
SELECT COUNT(*) AS total_rows FROM `FACT_PRODUCTION`;
SELECT COUNT(DISTINCT `Doc_Num`) AS distinct_work_orders FROM `FACT_PRODUCTION` WHERE `Doc_Num` IS NOT NULL;
SELECT SUM(`Rejected_Qty`) AS total_rejected_qty FROM `FACT_PRODUCTION`;
